int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];
    // Initialize a queue for BFS
    Queue<Integer> queue = new LinkedList<>();
    // Enqueue the root node
    queue.offer(0);
    // Initialize the minimum time required to collect all the apples and return to node 0
    int minTime = 0;
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue the next node from the queue
        int node = queue.poll();
        // If the node has not been visited before, mark it as visited
        if (!visited[node]) {
            visited[node] = true;
            // If the node has an apple, increment the minimum time required to collect it
            if (hasApple[node]) {
                minTime++;
            }
            // Enqueue the neighbors of the node that have not been visited before
            for (int neighbor : edges[node]) {
                if (!visited[neighbor]) {
                    queue.offer(neighbor);
                }
            }
        }
    }
    // Return the minimum time required to collect all the apples and return to node 0
    return minTime;
}
